export const VIEW={width:1280,height:720},LEVEL={width:4200,height:720,gate:2740,lever:2300};
export const platforms=[{x:0,y:600,w:900},{x:1010,y:600,w:1050},{x:2170,y:600,w:900},{x:3190,y:600,w:1010},{x:1270,y:505,w:260,h:95},{x:1530,y:430,w:300,h:170},{x:3340,y:505,w:250,h:95}];
export const overlaps=(a,b)=>a.x<b.x+b.w&&a.x+a.w>b.x&&a.y<b.y+b.h&&a.y+a.h>b.y;
export function create(){return{x:160,y:600,vx:0,vy:0,grounded:true,facing:1,crouching:false,attack:0,hp:3,camera:0,time:0,leverOn:false,vialTaken:false,enemy:{x:3470,y:600,hp:3,home:3470,facing:-1,lastHit:-1},attackId:0,complete:false,notice:"Cross the cloister and inspect its mechanisms.",noticeTime:6};}
export function step(s,input={},dt=1/60){dt=Math.min(dt,1/30);s.time+=dt;s.noticeTime=Math.max(0,s.noticeTime-dt);const dir=Number(!!input.right)-Number(!!input.left),height=s.crouching?84:120;s.crouching=s.grounded&&!!input.crouch;if(dir&&s.grounded&&!s.attack)s.facing=dir;if(input.attack&&!s.attack){s.attack=.36;s.attackId++;}s.attack=Math.max(0,s.attack-dt);if(s.grounded){s.vx=s.attack?0:dir*(s.crouching?90:235);if(input.jump&&!s.crouching){s.vy=-650;s.grounded=false;}}const oldX=s.x,oldY=s.y;s.x=Math.max(20,Math.min(LEVEL.width-20,s.x+s.vx*dt));for(const p of platforms)if(oldY>p.y&&oldY-height<p.y+(p.h??150)){if(s.vx>0&&oldX+13<=p.x&&s.x+13>p.x)s.x=p.x-13;if(s.vx<0&&oldX-13>=p.x+p.w&&s.x-13<p.x+p.w)s.x=p.x+p.w+13;}if(!s.leverOn&&oldX<LEVEL.gate&&s.x>=LEVEL.gate-28)s.x=LEVEL.gate-28;s.vy+=1850*dt;s.y+=s.vy*dt;s.grounded=false;for(const p of platforms)if(s.x+13>p.x&&s.x-13<p.x+p.w){if(s.vy>=0&&oldY<=p.y&&s.y>=p.y){s.y=p.y;s.vy=0;s.grounded=true;}else if(s.vy<0&&oldY-height>=p.y+(p.h??150)&&s.y-height<p.y+(p.h??150)){s.y=p.y+(p.h??150)+height;s.vy=0;}}if(s.y>850){s.x=160;s.y=600;s.vx=s.vy=0;s.grounded=true;}if(input.interact&&Math.abs(s.x-LEVEL.lever)<90&&!s.leverOn){s.leverOn=true;s.notice="The lever raises the cloister grate.";s.noticeTime=5;}if(!s.vialTaken&&Math.abs(s.x-1900)<38&&Math.abs(s.y-600)<130){s.vialTaken=true;s.hp=Math.min(5,s.hp+2);s.notice="Healing vial collected.";s.noticeTime=4;}const e=s.enemy;if(e.hp>0){e.facing=s.x>e.x?1:-1;e.x=e.home+Math.sin(s.time*.7)*55;const hit=s.attack>.1&&s.attack<.25?{x:s.facing>0?s.x:s.x-105,y:s.y-110,w:105,h:95}:null;if(hit&&e.lastHit!==s.attackId&&overlaps(hit,{x:e.x-25,y:e.y-125,w:50,h:125})){e.lastHit=s.attackId;e.hp--;}}if(s.x>4050&&!s.complete){s.complete=true;s.notice="Cloister blockout complete — the Cistern route is next.";s.noticeTime=999;}const focus=s.x+s.facing*80,screen=focus-s.camera;let target=s.camera;if(screen>760)target=focus-760;if(screen<420)target=focus-420;target=Math.max(0,Math.min(LEVEL.width-VIEW.width,target));s.camera+=(target-s.camera)*Math.min(1,dt*6);}
